// Bundles the backend modules and the Deno network layer into ONE file for the Supabase Edge Function.
const fs = require('fs');
const path = require('path');
const root = path.join(__dirname, '..');
const read = (p) => fs.readFileSync(path.join(root, p), 'utf8');
const main = read('supabase/api-main.ts');
const importLine = main.split('\n').find((l) => l.startsWith('import '));
const mainBody = main.split('\n').filter((l) => l !== importLine).join('\n');
const out = [
  '// @ts-nocheck',
  '// GENERATED by scripts/build-edge.js from backend/*.js + supabase/api-main.ts. Do not edit by hand.',
  importLine,
  read('backend/Core.js'), read('backend/Calc.js'), read('backend/Subcon.js'), read('backend/Service.js'), read('backend/PgAdapter.js'),
  mainBody
].join('\n');
fs.writeFileSync(path.join(root, 'supabase/functions/api/index.ts'), out);
console.log('wrote supabase/functions/api/index.ts (' + out.length + ' bytes)');
